const $ = (id) => document.getElementById(id);
const list = $("list");
const form = $("form");
const titleInput = $("title");
const LIMIT = 10;
let page = 1;

const showError = async (res) => { $("error").textContent = (await res.json()).error; };

async function load() {
  const q = new URLSearchParams({ page, limit: LIMIT });
  if ($("fTag").value.trim()) q.set("tag", $("fTag").value);
  if ($("fDone").value) q.set("done", $("fDone").value);
  const res = await fetch("/api/tasks?" + q);
  if (!res.ok) return showError(res);
  $("error").textContent = "";
  const { items: tasks, total } = await res.json();
  const pages = Math.max(1, Math.ceil(total / LIMIT));
  if (page > pages) { page = pages; return load(); }
  $("info").textContent = `Página ${page} de ${pages} (${total})`;
  $("prev").disabled = page <= 1;
  $("next").disabled = page >= pages;
  const now = new Date();
  const today = new Date(now - now.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  list.replaceChildren();
  for (const t of tasks) {
    const li = document.createElement("li");
    if (t.done) li.className = "done";
    const box = document.createElement("input");
    box.type = "checkbox"; box.checked = t.done;
    box.addEventListener("change", async () => {
      await fetch(`/api/tasks/${t.id}`, { method: "PATCH", headers: { "content-type": "application/json" }, body: JSON.stringify({ done: box.checked }) });
      load();
    });
    const text = document.createElement("span");
    text.textContent = t.title;
    li.append(box, text);
    for (const tag of t.tags) {
      const chip = document.createElement("span");
      chip.className = "tag"; chip.textContent = tag;
      li.append(chip);
    }
    if (t.due) {
      const due = document.createElement("span");
      due.textContent = "Prazo: " + t.due;
      if (!t.done && t.due < today) { due.className = "late"; due.textContent += " (atrasada)"; }
      li.append(due);
    }
    const del = document.createElement("button");
    del.textContent = "Excluir";
    del.addEventListener("click", async () => { await fetch(`/api/tasks/${t.id}`, { method: "DELETE" }); load(); });
    li.append(del);
    list.append(li);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  const res = await fetch("/api/tasks", {
    method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify({ title: titleInput.value, tags: $("tags").value.split(",").filter((x) => x.trim()), due: $("due").value || null }),
  });
  if (!res.ok) return showError(res);
  form.reset();
  load();
});
$("prev").addEventListener("click", () => { page--; load(); });
$("next").addEventListener("click", () => { page++; load(); });
for (const id of ["fTag", "fDone"]) $(id).addEventListener("input", () => { page = 1; load(); });
load();

