const post = (base, body) => json(base, "/api/tasks", "POST", { title: "t", ...body });

test("normaliza tags", () => withServer(async (base) => {
  const t = await (await post(base, { tags: [" Casa ", "casa", "CASA", "x"], due: "2024-02-29" })).json();
  assert.deepEqual(t.tags, ["casa", "x"]);
  assert.equal(t.due, "2024-02-29");
}));

test("valida tags, due e título", () => withServer(async (base) => {
  const bad = [
    { tags: ["  "] }, { tags: ["a".repeat(21)] }, { tags: ["a", "b", "c", "d", "e", "f"] },
    { tags: [1] }, { tags: "a" }, { due: "2023-02-29" }, { due: "2024-1-1" }, { due: 5 },
    { title: "a".repeat(101) },
  ];
  for (const b of bad) assert.equal((await post(base, b)).status, 400, JSON.stringify(b));
  assert.equal((await post(base, { title: "a".repeat(100), tags: ["a".repeat(20)] })).status, 201);
}));

test("PATCH altera tags e due, null limpa, inválido não altera nada", () => withServer(async (base) => {
  const t = await (await post(base, { due: "2030-01-01" })).json();
  const r = await (await json(base, `/api/tasks/${t.id}`, "PATCH", { tags: ["A"], due: null })).json();
  assert.deepEqual([r.tags, r.due], [["a"], null]);
  assert.equal((await json(base, `/api/tasks/${t.id}`, "PATCH", { tags: ["ok"], due: "xx" })).status, 400);
  const list = await (await json(base, "/api/tasks")).json();
  assert.deepEqual(list.items[0].tags, ["a"]);
}));

test("paginação e filtros", () => withServer(async (base) => {
  for (let i = 1; i <= 12; i++) await post(base, { title: "t" + i, tags: i % 2 ? ["Impar"] : [], due: i <= 3 ? "2000-01-01" : "2999-01-01" });
  const ids = (await (await json(base, "/api/tasks?limit=1")).json()).items[0].id;
  await json(base, `/api/tasks/${ids + 1}`, "PATCH", { done: true }); // t2
  const get = async (q) => (await json(base, "/api/tasks?" + q)).json();
  let r = await get("");
  assert.deepEqual([r.page, r.limit, r.total, r.items.length], [1, 10, 12, 10]);
  r = await get("page=2&limit=5");
  assert.deepEqual(r.items.map((t) => t.title), ["t6", "t7", "t8", "t9", "t10"]);
  assert.equal((await get("tag=IMPAR")).total, 6);
  assert.equal((await get("done=true")).total, 1);
  assert.equal((await get("done=false")).total, 11);
  assert.deepEqual((await get("overdue=true")).items.map((t) => t.title), ["t1", "t3"]);
  assert.equal((await get("overdue=true&tag=impar&done=false")).total, 2);
  assert.equal((await get("page=9")).items.length, 0);
  for (const q of ["page=0", "page=x", "limit=51", "limit=0", "done=maybe", "overdue=false", "tag="])
    assert.equal((await json(base, "/api/tasks?" + q)).status, 400, q);
}));
